"""Hive auto-rig: Blender builder (generated by hive-rig).

Builds the skinned mesh, a deform armature and an animator control rig with FK
and IK controls, pole targets and an IK/FK blend slider on every limb.

It also adds a "Hive" tab to the 3D view sidebar (press N) for editing the rig's
guides, adding or removing components (fingers, tails) and rebuilding the rig.
Rebuilding keeps your skin weights except where new bones were added.

Run inside Blender 3.6+ (Scripting tab > Open > Run Script), or headless:
    blender --background --python <this file> -- --save out.blend
Running it again in a file that already has this rig only brings the Hive tab back.
"""

import json
import os
import subprocess
import sys

import bpy
from mathutils import Matrix, Vector

RIG_DATA = json.loads(r"""__HIVE_RIG_JSON__""")
GLB_PATH = r"""__HIVE_GLB_PATH__"""
# The hive-rig program, used to rebuild from edited guides. Change this if you
# moved it since generating this script.
HIVE_EXE = r"""__HIVE_EXE__"""
OUT_DIR = os.path.dirname(GLB_PATH)


def to_blender(p):
    """Hive space is Y-up / +Z forward (glTF); Blender is Z-up / -Y forward."""
    return Vector((p[0], -p[2], p[1]))


def from_blender(v):
    return [v[0], v[2], -v[1]]


def build(RIG, geo=None):
    """Build the armature, controls and skin for RIG. With `geo`, re-skin that
    existing mesh object instead of creating a new one."""
    NAME = RIG["name"]
    BONES = RIG["skeleton"]["bones"]
    CONTROLS = RIG["controls"]["controls"]
    CHAINS = RIG["controls"]["ik_chains"]

    def copy_rule(bone):
        """Bones without a deforming parent, and face joints, follow position too; the rest only rotate."""
        parent = bone["parent"]
        moves = bone.get("translate") or parent is None or not BONES[parent]["deform"]
        return "COPY_TRANSFORMS" if moves else "COPY_ROTATION"

    # --------------------------------------------------------------------------- scene
    def new_collection(name, parent):
        coll = bpy.data.collections.new(name)
        parent.children.link(coll)
        return coll


    root_coll = bpy.data.collections.get(NAME) or new_collection(NAME, bpy.context.scene.collection)
    widget_coll = new_collection(NAME + "_widgets", root_coll)
    widget_coll.hide_viewport = True
    widget_coll.hide_render = True

    # --------------------------------------------------------------------------- mesh
    if geo is None:
        positions = RIG["mesh"]["positions"]
        indices = RIG["mesh"]["indices"]
        mesh = bpy.data.meshes.new(NAME + "_mesh")
        mesh.from_pydata(
            [to_blender(p) for p in positions],
            [],
            [indices[i : i + 3] for i in range(0, len(indices), 3)],
        )
        mesh.update()
        for poly in mesh.polygons:
            poly.use_smooth = True
        geo = bpy.data.objects.new(NAME + "_geo", mesh)
        root_coll.objects.link(geo)
    else:
        # Rebuilding: keep the user's mesh object (materials, modifiers, edits) and
        # replace only its skin.
        geo.vertex_groups.clear()
        for m in [m for m in geo.modifiers if m.type == "ARMATURE"]:
            geo.modifiers.remove(m)
        world = geo.matrix_world.copy()
        geo.parent = None
        geo.matrix_world = world

    # --------------------------------------------------------------------------- widgets
    def outline_widget(c, bone_matrix):
        """A wire mesh of the control's outline (hive-rig's model-space lines),
        expressed in the bone's rest space so the custom shape lands exactly there."""
        to_bone = bone_matrix.inverted()
        verts, edges = [], []
        for line in c["outline"]:
            start = len(verts)
            closed = len(line) > 2 and line[0] == line[-1]
            points = line[:-1] if closed else line
            verts.extend(to_bone @ to_blender(p) for p in points)
            edges.extend((start + i, start + i + 1) for i in range(len(points) - 1))
            if closed:
                edges.append((start + len(points) - 1, start))
        me = bpy.data.meshes.new("WGT_" + c["name"])
        me.from_pydata(verts, edges, [])
        obj = bpy.data.objects.new("WGT_" + NAME + "_" + c["name"], me)
        widget_coll.objects.link(obj)
        return obj

    # --------------------------------------------------------------------------- armature
    arm_data = bpy.data.armatures.new(NAME + "_rig")
    arm_data.display_type = "STICK"
    rig = bpy.data.objects.new(NAME + "_rig", arm_data)
    rig.show_in_front = True
    root_coll.objects.link(rig)

    for obj in bpy.context.view_layer.objects:
        if obj is not None:  # entries for objects removed by a rebuild
            obj.select_set(False)
    bpy.context.view_layer.objects.active = rig
    rig.select_set(True)
    bpy.ops.object.mode_set(mode="EDIT")

    edit = arm_data.edit_bones
    for b in BONES:
        eb = edit.new(b["name"])
        eb.head = to_blender(b["head"])
        eb.tail = to_blender(b["tail"])
        eb.use_deform = b["deform"]
    for b in BONES:
        if b["parent"] is not None:
            edit[b["name"]].parent = edit[BONES[b["parent"]]["name"]]

    bone_by_name = {b["name"]: b for b in BONES}
    chain_end_ik = {c["ik_control"]: c["end"] for c in CHAINS}

    for c in CONTROLS:
        eb = edit.new(c["name"])
        eb.use_deform = False
        template = c["bone"] if c["kind"] in ("fk", "root") else chain_end_ik.get(c["name"])
        if template:
            # Same rest orientation as the bone it drives, so constraints add no offset.
            src = edit[template]
            eb.head, eb.tail, eb.roll = src.head.copy(), src.tail.copy(), src.roll
        else:
            head = to_blender(c["position"])
            eb.head = head
            eb.tail = head + to_blender(c["axis"]).normalized() * max(c["size"], 0.02)

    for c in CONTROLS:
        parent = c["parent"]
        if parent["type"] in ("control", "bone"):
            edit[c["name"]].parent = edit[parent["name"]]

    MCH = []  # helper bones: hidden, never animated directly


    def mch(name, like=None, head=None, parent=None):
        """Helper bone copying `like`'s rest geometry, or standing upright at `head`."""
        eb = edit.new(name)
        eb.use_deform = False
        if like is not None:
            src = edit[like]
            eb.head, eb.tail, eb.roll = src.head.copy(), src.tail.copy(), src.roll
        else:
            # Upright with zero roll, so local X is world X: rotating about X pitches the foot.
            eb.head = head
            eb.tail = head + Vector((0.0, 0.0, 0.05))
            eb.roll = 0.0
        if parent is not None:
            eb.parent = edit[parent]
        MCH.append(name)
        return name


    # Space switching: each switchable control hangs under a parentless helper that an
    # Armature constraint binds to whichever space is selected.
    space_bone = {}
    for c in CONTROLS:
        if c.get("spaces"):
            space_bone[c["name"]] = mch("MCH_%s_space" % c["name"], like=c["name"])
            edit[c["name"]].parent = edit[space_bone[c["name"]]]

    # Reverse foot: heel > toe tip > ball > ankle under the foot IK control.
    foot_ik_target = {}
    for chain in CHAINS:
        foot = chain.get("foot")
        if not foot:
            continue
        n = chain["name"]
        heel = mch("MCH_%s_heel" % n, head=to_blender(foot["heel"]), parent=chain["ik_control"])
        toe = mch("MCH_%s_toe" % n, head=to_blender(foot["toe_tip"]), parent=heel)
        ball = mch("MCH_%s_ball" % n, head=to_blender(foot["ball"]), parent=toe)
        foot_ik_target[n] = mch("MCH_%s_ankle" % n, like=chain["end"], parent=ball)
        # The toe control follows the foot in FK and stays planted on the toe pivot in IK.
        flat = mch("MCH_%s_toe_flat" % n, like=foot["ball_bone"], parent=toe)
        ball_space = mch("MCH_%s_ball_space" % n, like=foot["ball_bone"], parent=chain["end"])
        edit[foot["ball_control"]].parent = edit[ball_space]
        chain["_flat"], chain["_ball_space"] = flat, ball_space
        chain["_pivots"] = (heel, toe, ball)

    # Three-segment legs: the hock control rides on the foot goal (so it follows the
    # roll) and carries a copy of the hock bone. The thigh and calf solve to that
    # copy's head (the hock point) and the hock bone takes its rotation.
    hock_target = {}
    for chain in CHAINS:
        hock = chain.get("hock")
        if not hock:
            continue
        goal = foot_ik_target.get(chain["name"], chain["ik_control"])
        edit[hock["control"]].parent = edit[goal]
        # A stretching calf scales; the hock keeps its length so the paw lands on the goal.
        edit[hock["bone"]].inherit_scale = "NONE"
        hock_target[chain["name"]] = mch("MCH_%s_hock" % chain["name"], like=hock["bone"], parent=hock["control"])


    def signed_angle(u, v, normal):
        a = u.angle(v)
        if u.cross(v).angle(normal) < 1:
            a = -a
        return a


    def pole_angle(base, ik, pole):
        normal = (ik.tail - base.head).cross(pole - base.head)
        projected = normal.cross(base.tail - base.head)
        return signed_angle(base.x_axis, projected, base.tail - base.head)


    pole_angles = {
        c["name"]: pole_angle(edit[c["upper"]], edit[c["lower"]], edit[c["pole_control"]].head)
        for c in CHAINS
    }

    bpy.ops.object.mode_set(mode="POSE")

    # --------------------------------------------------------------------------- bone collections / colours
    has_collections = hasattr(arm_data, "collections")
    if has_collections:
        def_coll = arm_data.collections.new("DEF")
        ctrl_coll = arm_data.collections.new("CTRL")
        def_coll.is_visible = False

    pose = rig.pose.bones
    for b in BONES:
        if has_collections:
            def_coll.assign(arm_data.bones[b["name"]])
    if has_collections:
        mch_coll = arm_data.collections.new("MCH")
        mch_coll.is_visible = False
        for name in MCH:
            mch_coll.assign(arm_data.bones[name])
    for name in MCH:
        pose[name].rotation_mode = "XYZ"

    for c in CONTROLS:
        pb = pose[c["name"]]
        # The outline already sits at the control's position (e.g. clavicle at the shoulder).
        pb.custom_shape = outline_widget(c, pb.bone.matrix_local)
        pb.use_custom_shape_bone_size = False
        pb.rotation_mode = "XYZ"
        if c["kind"] == "hock" or (
            c["kind"] == "fk" and c["bone"] and copy_rule(bone_by_name[c["bone"]]) == "COPY_ROTATION"
        ):
            pb.lock_location = (True, True, True)
        if has_collections:
            ctrl_coll.assign(arm_data.bones[c["name"]])
        if hasattr(pb, "color"):
            pb.color.palette = "CUSTOM"
            col = c["color"]
            pb.color.custom.normal = col
            pb.color.custom.select = [min(1.0, x + 0.35) for x in col]
            pb.color.custom.active = (1.0, 1.0, 1.0)

    # --------------------------------------------------------------------------- constraints
    def add_driver(owner, path, control, prop, expression, index=-1):
        """Drive owner.path from a custom property on a control (simple expressions only,
        so it works without enabling Python auto-run)."""
        fcurve = owner.driver_add(path, index) if index >= 0 else owner.driver_add(path)
        drv = fcurve.driver
        drv.type = "SCRIPTED"
        var = drv.variables.new()
        var.name = prop
        var.type = "SINGLE_PROP"
        var.targets[0].id = rig
        var.targets[0].data_path = 'pose.bones["%s"]["%s"]' % (control, prop)
        drv.expression = expression
        return fcurve


    def add_blend_driver(con, ik_control):
        add_driver(con, "influence", ik_control, "ik_fk", "ik_fk")


    def add_property(pb, name, value, lo, hi, description):
        pb[name] = value
        try:
            pb.id_properties_ui(name).update(min=lo, max=hi, soft_min=lo, soft_max=hi, description=description)
        except AttributeError:
            pass


    for c in CONTROLS:
        if c["kind"] in ("fk", "root") and c["bone"]:
            con = pose[c["bone"]].constraints.new(copy_rule(bone_by_name[c["bone"]]))
            con.name = "FK"
            con.target = rig
            con.subtarget = c["name"]

    # Eyes: each eye bone tracks its aim control (it points at it at rest, so no offset).
    for c in CONTROLS:
        if c["kind"] == "aim" and c["bone"]:
            con = pose[c["bone"]].constraints.new("DAMPED_TRACK")
            con.name = "Aim"
            con.target = rig
            con.subtarget = c["name"]
            con.track_axis = "TRACK_Y"

    for chain in CHAINS:
        ik_pb = pose[chain["ik_control"]]
        add_property(ik_pb, "ik_fk", float(chain["default_blend"]), 0.0, 1.0, "0 = FK, 1 = IK")
        add_property(ik_pb, "stretch", float(chain["default_stretch"]), 0.0, 1.0,
                     "Let the limb stretch to reach the IK control")
        goal = foot_ik_target.get(chain["name"], chain["ik_control"])
        hock = chain.get("hock")

        ik = pose[chain["lower"]].constraints.new("IK")
        ik.name = "IK"
        ik.target = rig
        ik.subtarget = hock_target[chain["name"]] if hock else goal
        ik.use_stretch = True
        for bone in (chain["upper"], chain["lower"]):
            add_driver(pose[bone], "ik_stretch", chain["ik_control"], "stretch", "stretch * 0.1")
        ik.pole_target = rig
        ik.pole_subtarget = chain["pole_control"]
        ik.pole_angle = pole_angles[chain["name"]]
        ik.chain_count = 2
        add_blend_driver(ik, chain["ik_control"])

        if hock:
            seg = pose[hock["bone"]].constraints.new("COPY_ROTATION")
            seg.name = "IK Hock"
            seg.target = rig
            seg.subtarget = hock_target[chain["name"]]
            add_blend_driver(seg, chain["ik_control"])

        rot = pose[chain["end"]].constraints.new("COPY_ROTATION")
        rot.name = "IK Rotation"
        rot.target = rig
        rot.subtarget = goal
        add_blend_driver(rot, chain["ik_control"])

        foot = chain.get("foot")
        if foot:
            add_property(ik_pb, "roll", 0.0, -90.0, 120.0,
                         "Negative rocks back on the heel; positive rolls through the ball, then the toe")
            brk = float(foot["break_angle"])
            heel, toe, ball = chain["_pivots"]
            d2r = "0.0174533"
            add_driver(pose[heel], "rotation_euler", chain["ik_control"], "roll", "min(roll, 0) * " + d2r, 0)
            add_driver(pose[ball], "rotation_euler", chain["ik_control"], "roll",
                       "min(max(roll, 0), %g) * %s" % (brk, d2r), 0)
            add_driver(pose[toe], "rotation_euler", chain["ik_control"], "roll",
                       "max(roll - %g, 0) * %s" % (brk, d2r), 0)
            follow = pose[chain["_ball_space"]].constraints.new("COPY_TRANSFORMS")
            follow.name = "IK Toe"
            follow.target = rig
            follow.subtarget = chain["_flat"]
            add_blend_driver(follow, chain["ik_control"])

    # Twist helpers take a share of their source bone's twist (rotation about its length).
    for b in BONES:
        twist = b.get("twist")
        if not twist:
            continue
        con = pose[b["name"]].constraints.new("COPY_ROTATION")
        con.name = "Twist"
        con.target = rig
        con.subtarget = twist["source"]
        con.use_x = con.use_z = False
        con.use_y = True
        con.invert_y = twist["factor"] < 0
        con.owner_space = con.target_space = "LOCAL"
        con.mix_mode = "ADD"
        con.influence = abs(twist["factor"])

    # Space switching.
    for c in CONTROLS:
        if not c.get("spaces"):
            continue
        pb = pose[c["name"]]
        add_property(pb, "space", 0, 0, len(c["spaces"]) - 1,
                     "Follow: " + ", ".join("%d = %s" % (i, s) for i, s in enumerate(c["spaces"])))
        con = pose[space_bone[c["name"]]].constraints.new("ARMATURE")
        con.name = "Space"
        for i, space in enumerate(c["spaces"]):
            t = con.targets.new()
            t.target = rig
            t.subtarget = space
            t.weight = 1.0 if i == 0 else 0.0
            add_driver(t, "weight", c["name"], "space", "1 - min(abs(space - %d), 1)" % i)

    bpy.ops.object.mode_set(mode="OBJECT")

    # --------------------------------------------------------------------------- skin
    for b in BONES:
        if b["deform"]:
            geo.vertex_groups.new(name=b["name"])
    groups = {vg.name: vg for vg in geo.vertex_groups}
    for v, (joints, weights) in enumerate(zip(RIG["skin"]["joints"], RIG["skin"]["weights"])):
        for j, w in zip(joints, weights):
            if w > 0.0:
                groups[BONES[j]["name"]].add([v], w, "REPLACE")

    mod = geo.modifiers.new("Armature", "ARMATURE")
    mod.object = rig
    geo.parent = rig

    # What the Hive panel needs to edit guides and rebuild, kept with the rig so it
    # survives saving and reopening the file.
    rig["hive_name"] = NAME
    rig["hive_guides"] = json.dumps(RIG["guides"])
    rig["hive_dir"] = OUT_DIR
    rig["hive_anim"] = json.dumps(animator_data(RIG, foot_ik_target))
    bpy.context.view_layer.objects.active = rig
    print("hive-rig: built %s with %d bones and %d controls" % (NAME, len(BONES), len(CONTROLS)))
    return rig, geo


# --------------------------------------------------------------------------- animator tools
# IK/FK matching, pose mirroring, reset and space switching. Which controls make
# up each limb and which controls are left/right twins come from hive-rig (the
# rig's ik_chains and mirror_pairs), kept on the armature as `hive_anim`.
ANIM_PROPS = ("ik_fk", "stretch", "roll", "space")


def animator_data(RIG, goals):
    controls = RIG["controls"]
    limbs, defaults = [], {}
    for c in controls["ik_chains"]:
        limbs.append({
            "name": c["name"], "upper": c["upper"], "lower": c["lower"], "end": c["end"],
            "ik": c["ik_control"], "pole": c["pole_control"], "fk": c["fk_controls"],
            "goal": goals.get(c["name"], c["ik_control"]),
        })
        d = defaults.setdefault(c["ik_control"], {})
        d.update(ik_fk=float(c["default_blend"]), stretch=float(c["default_stretch"]))
        if c.get("foot"):
            d["roll"] = 0.0
    spaces = {}
    for c in controls["controls"]:
        if c.get("spaces"):
            spaces[c["name"]] = c["spaces"]
            defaults.setdefault(c["name"], {})["space"] = 0
    return {
        "controls": [c["name"] for c in controls["controls"]],
        "limbs": limbs,
        "mirror": controls.get("mirror_pairs", []),
        "spaces": spaces,
        "defaults": defaults,
    }


def anim_data(rig):
    return json.loads(rig["hive_anim"])


def refresh(rig):
    rig.update_tag()
    bpy.context.view_layer.update()


def key_controls(rig, names):
    """Key what the tools changed when auto-keying is on."""
    if not bpy.context.scene.tool_settings.use_keyframe_insert_auto:
        return
    for n in names:
        pb = rig.pose.bones[n]
        pb.keyframe_insert("location")
        pb.keyframe_insert("rotation_quaternion" if pb.rotation_mode == "QUATERNION" else
                           "rotation_axis_angle" if pb.rotation_mode == "AXIS_ANGLE" else "rotation_euler")
        for prop in ANIM_PROPS:
            if prop in pb.keys():
                pb.keyframe_insert('["%s"]' % prop)


def limb_of(rig, name):
    return next(l for l in anim_data(rig)["limbs"] if l["name"] == name)


def rotation_only(m):
    """The matrix without scale (a stretched IK bone), so FK controls stay unscaled."""
    return m.normalized()


def limb_frame(a, b, c, fallback_bend):
    """Axes of a limb: along the reach (root to end), toward the bend of the middle
    joint, and their normal. A straight limb has no bend; `fallback_bend` stands in."""
    along = (c - a).normalized()
    bend = (b - a) - along * (b - a).dot(along)
    if bend.length < 1e-3 * (b - a).length:
        bend = fallback_bend - along * fallback_bend.dot(along)
    bend.normalize()
    return Matrix((along, bend, along.cross(bend))).transposed()


def pole_position(rig, limb, a, b, c, upper_matrix):
    """The pole in front of the middle joint, in the plane of the limb: it keeps
    the place it had relative to the limb's frame at rest, so the IK solve lands
    on the same bend. A straight limb has no plane; then the rest bend is carried
    along by the upper bone."""
    bones = rig.data.bones
    ra, rb, rc = (bones[limb[k]].head_local for k in ("upper", "lower", "end"))
    rest_pole = bones[limb["pole"]].head_local
    rest = limb_frame(ra, rb, rc, rest_pole - rb)
    rest_upper = bones[limb["upper"]].matrix_local.to_3x3().normalized()
    carried = upper_matrix.to_3x3().normalized() @ rest_upper.inverted() @ (rest @ Vector((0.0, 1.0, 0.0)))
    now = limb_frame(a, b, c, carried)
    return b + now @ (rest.transposed() @ (rest_pole - rb))


def ik_to_fk(rig, name):
    """Snap the FK controls onto the IK pose, then switch the limb to FK."""
    limb = limb_of(rig, name)
    pose = rig.pose.bones
    ik = pose[limb["ik"]]
    ik["ik_fk"] = 1.0
    refresh(rig)
    targets = [rotation_only(pose[limb[k]].matrix) for k in ("upper", "lower", "end")]
    for fk, m in zip(limb["fk"], targets):
        pb = pose[fk]
        pb.matrix = m
        if all(pb.lock_location):
            pb.location = (0.0, 0.0, 0.0)
        refresh(rig)
    ik["ik_fk"] = 0.0
    refresh(rig)
    key_controls(rig, limb["fk"] + [limb["ik"]])


def fk_to_ik(rig, name):
    """Move the IK control and pole onto the FK pose, then switch the limb to IK."""
    limb = limb_of(rig, name)
    pose = rig.pose.bones
    refresh(rig)
    fk = [rotation_only(pose[n].matrix) for n in limb["fk"]]
    ik, goal = pose[limb["ik"]], pose[limb["goal"]]
    # The IK goal can sit below the control (a rolled foot); keep that offset.
    offset = ik.matrix.inverted() @ goal.matrix
    ik.matrix = fk[2] @ offset.inverted()
    refresh(rig)
    pole = pose[limb["pole"]]
    a, b, c = fk[0].translation, fk[1].translation, fk[2].translation
    m = pole.matrix.copy()
    m.translation = pole_position(rig, limb, a, b, c, fk[0])
    pole.matrix = m
    ik["ik_fk"] = 1.0
    refresh(rig)
    # How the solver turns the limb's plane toward the pole is its own business;
    # turn the pole about the reach until the middle joint lands on the FK one.
    along = (c - a).normalized()
    for _ in range(8):
        want = b - a - along * (b - a).dot(along)
        got = pose[limb["lower"]].head - a
        got -= along * got.dot(along)
        if want.length < 1e-6 or got.length < 1e-6:
            break
        angle = got.angle(want)
        if angle < 1e-5:
            break
        if got.cross(want).dot(along) < 0:
            angle = -angle
        m = pole.matrix.copy()
        m.translation = a + Matrix.Rotation(angle, 3, along) @ (m.translation - a)
        pole.matrix = m
        refresh(rig)
    key_controls(rig, [limb["ik"], limb["pole"]])


def mirror_pose(rig, names=None, source="left"):
    """Copy controls' poses onto their twins on the other side. `names` are the
    controls to copy from (their twins receive the pose); without names every
    `source`-side control is copied. Each pose is mirrored relative to the
    control's parent, so the result is symmetric when the centre is."""
    data = anim_data(rig)
    twin = {}
    for left, right in data["mirror"]:
        twin[left], twin[right] = right, left
    lefts = {left for left, _ in data["mirror"]}
    if names:
        picked = [n for n in names if n in twin]
        # With both twins picked, the source side wins.
        copies = [(n, twin[n]) for n in picked if twin[n] not in picked or (n in lefts) == (source == "left")]
    else:
        copies = [(l, r) if source == "left" else (r, l) for l, r in data["mirror"]]
    pose, bones = rig.pose.bones, rig.data.bones
    flip = Matrix.Scale(-1.0, 3, (1.0, 0.0, 0.0))
    # Read every source first, so swapping both sides at once is consistent.
    poses = [(src, dst, pose[src].matrix_basis.copy(), {p: pose[src][p] for p in ANIM_PROPS if p in pose[src].keys()})
             for src, dst in copies]
    for src, dst, basis, props in poses:
        # The rest frames of twins are mirror images up to an axis flip `f`;
        # conjugating the source's local pose by it gives the twin's.
        rs = bones[src].matrix_local.to_3x3().normalized()
        rd = bones[dst].matrix_local.to_3x3().normalized()
        f = (rs.inverted() @ flip @ rd).to_4x4()
        pose[dst].matrix_basis = f.inverted() @ basis @ f
        for p, v in props.items():
            if p in pose[dst].keys():
                pose[dst][p] = v
    refresh(rig)
    key_controls(rig, [dst for _, dst in copies])
    return len(copies)


def reset_pose(rig, names=None):
    """Put controls (all, or `names`) back to the bind pose and default settings."""
    data = anim_data(rig)
    names = [n for n in (names or data["controls"]) if n in data["controls"]]
    pose = rig.pose.bones
    for n in names:
        pose[n].matrix_basis = Matrix.Identity(4)
        for p, v in data["defaults"].get(n, {}).items():
            pose[n][p] = v
    refresh(rig)
    key_controls(rig, names)
    return len(names)


def set_bone_selected(pb, value):
    if "select" in pb.bl_rna.properties:  # Blender 5: selection lives on the pose bone
        pb.select = value
    else:
        pb.bone.select = value


def bone_selected(pb):
    return pb.select if "select" in pb.bl_rna.properties else pb.bone.select


def selected_controls(rig):
    controls = set(anim_data(rig)["controls"])
    return [pb.name for pb in rig.pose.bones if pb.name in controls and bone_selected(pb)]


def select_controls(rig):
    controls = set(anim_data(rig)["controls"])
    for pb in rig.pose.bones:
        set_bone_selected(pb, pb.name in controls)
    return len(controls)


def switch_space(rig, control, index):
    """Change a control's space without moving it."""
    pb = rig.pose.bones[control]
    refresh(rig)
    keep = pb.matrix.copy()
    pb["space"] = int(index)
    refresh(rig)
    pb.matrix = keep
    refresh(rig)
    key_controls(rig, [control])


# --------------------------------------------------------------------------- guides
# Guides are empties named GDE_<rig>__<component>__<guide>. Moving them and
# pressing Rebuild writes <name>.guides.json and asks hive-rig to rebuild.


def find_rig(context=None):
    """The Hive rig for the active object (the rig, its mesh, or one of its guides)."""
    context = context or bpy.context
    obj = context.active_object
    candidates = [obj] if obj else []
    if obj is not None:
        candidates.append(obj.parent)
        name = obj.get("hive_rig")
        if name:
            candidates.append(bpy.data.objects.get(name))
    candidates += [o for o in bpy.data.objects if o.get("hive_guides")]
    return next((o for o in candidates if o is not None and o.get("hive_guides")), None)


def guide_objects(rig):
    return [o for o in bpy.data.objects if o.get("hive_rig") == rig.name]


def rig_mesh(rig):
    return next((o for o in rig.children if o.type == "MESH"), None)


def guides_of(rig):
    """Current guides: from the guide empties when they're out, else as last built."""
    data = json.loads(rig["hive_guides"])
    by_key = {(o["hive_component"], o["hive_guide"]): o for o in guide_objects(rig)}
    for comp in data["components"]:
        for g in comp["guides"]:
            obj = by_key.get((comp["id"], g["name"]))
            if obj is not None:
                # Guides are never parented, and `location` is current even before
                # Blender refreshes matrix_world for newly created empties.
                g["position"] = from_blender(obj.location)
    return data


def remove_guides(rig):
    for o in guide_objects(rig):
        bpy.data.objects.remove(o, do_unlink=True)
    coll = bpy.data.collections.get(rig["hive_name"] + "_guides")
    if coll is not None:
        bpy.data.collections.remove(coll)


def show_guides(rig, data=None):
    """Put out an empty for every guide and hide the controls while editing."""
    data = data or guides_of(rig)
    remove_guides(rig)
    name = rig["hive_name"]
    parent_coll = bpy.data.collections.get(name) or bpy.context.scene.collection
    coll = bpy.data.collections.new(name + "_guides")
    parent_coll.children.link(coll)
    size = 0.012 * data["body"]["height"]
    colors = {"left": (0.1, 0.45, 1.0, 1.0), "right": (1.0, 0.15, 0.15, 1.0), "center": (1.0, 0.85, 0.1, 1.0)}
    for comp in data["components"]:
        for g in comp["guides"]:
            obj = bpy.data.objects.new("GDE_%s__%s__%s" % (name, comp["id"], g["name"]), None)
            obj.empty_display_type = "SPHERE"
            obj.empty_display_size = size
            obj.location = to_blender(g["position"])
            obj.show_in_front = True
            obj.color = colors.get(comp.get("side", "center"), colors["center"])
            obj["hive_rig"] = rig.name
            obj["hive_component"] = comp["id"]
            obj["hive_guide"] = g["name"]
            coll.objects.link(obj)
    rig.hide_set(True)
    rig["hive_guides"] = json.dumps(data)


def mirror_guides(rig, source="left"):
    """Copy one side's guide positions onto the other, mirrored across the body."""
    data = guides_of(rig)
    cx = data["body"]["center_x"]
    other = "right" if source == "left" else "left"
    suffix = {"left": "_l", "right": "_r"}
    comps = {c["id"]: c for c in data["components"]}
    for comp in data["components"]:
        if comp.get("side") != source or not comp["id"].endswith(suffix[source]):
            continue
        twin = comps.get(comp["id"][: -len(suffix[source])] + suffix[other])
        if twin is None or len(twin["guides"]) != len(comp["guides"]):
            continue
        for g, t in zip(comp["guides"], twin["guides"]):
            x, y, z = g["position"]
            t["position"] = [2 * cx - x, y, z]
    show_guides(rig, data)


def run_hive(*args):
    if not HIVE_EXE or not os.path.isfile(HIVE_EXE):
        raise RuntimeError("hive-rig program not found; set HIVE_EXE at the top of this script (%r)" % HIVE_EXE)
    done = subprocess.run([HIVE_EXE] + [str(a) for a in args], capture_output=True, text=True)
    if done.returncode != 0:
        raise RuntimeError("hive-rig %s failed: %s" % (args[0], (done.stderr or done.stdout).strip()))
    return done.stdout


def files(rig):
    name, folder = rig["hive_name"], rig["hive_dir"]
    return os.path.join(folder, name + ".guides.json"), os.path.join(folder, name + ".hive.json")


def write_guides(rig, data):
    path = files(rig)[0]
    with open(path, "w") as f:
        json.dump(data, f, indent=2)
    return path


def change_components(rig, *args):
    """Run `hive-rig add|remove <guides> ...` and show the updated guides."""
    path = write_guides(rig, guides_of(rig))
    out = run_hive(args[0], path, *args[1:])
    with open(path) as f:
        show_guides(rig, json.load(f))
    return out.strip()


def read_weights(geo):
    names = {vg.index: vg.name for vg in geo.vertex_groups}
    return [{names[g.group]: g.weight for g in v.groups if g.weight > 0.0} for v in geo.data.vertices]


def rebuild(rig, keep_weights=True):
    """Rebuild the rig from its guides. With keep_weights, vertices keep their
    current weights unless the new rig weights them to a bone that didn't exist."""
    guides_path, hive_path = files(rig)
    write_guides(rig, guides_of(rig))
    run_hive("rebuild", hive_path, "--guides", guides_path)
    with open(hive_path) as f:
        data = json.load(f)

    geo = rig_mesh(rig)
    old = read_weights(geo) if geo is not None and keep_weights else None
    old_bones = {b.name for b in rig.data.bones}
    name = rig["hive_name"]
    remove_guides(rig)
    arm = rig.data
    bpy.data.objects.remove(rig, do_unlink=True)
    bpy.data.armatures.remove(arm)
    widgets = bpy.data.collections.get(name + "_widgets")
    if widgets is not None:
        for o in list(widgets.objects):
            bpy.data.objects.remove(o, do_unlink=True)
        bpy.data.collections.remove(widgets)

    bpy.context.view_layer.update()
    rig, geo = build(data, geo)
    kept = 0
    if old is not None and len(old) == len(geo.data.vertices):
        groups = {vg.name: vg for vg in geo.vertex_groups}
        new = read_weights(geo)
        for v, (before, after) in enumerate(zip(old, new)):
            if not before or not set(after) <= old_bones:
                continue
            for g in after:
                groups[g].remove([v])
            for g, w in before.items():
                if g in groups:
                    groups[g].add([v], w, "REPLACE")
            kept += 1
    print("hive-rig: rebuilt %s; kept the weights of %d vertices" % (name, kept))
    return rig


# --------------------------------------------------------------------------- UI


class HIVE_OT_edit_guides(bpy.types.Operator):
    bl_idname = "hive.edit_guides"
    bl_label = "Edit Guides"
    bl_description = "Show the guides so you can move them; Rebuild applies them"

    def execute(self, context):
        show_guides(find_rig(context))
        return {"FINISHED"}


class HIVE_OT_mirror_guides(bpy.types.Operator):
    bl_idname = "hive.mirror_guides"
    bl_label = "Mirror Left to Right"
    bl_description = "Copy the left guides onto the right side"

    def execute(self, context):
        mirror_guides(find_rig(context))
        return {"FINISHED"}


class HIVE_OT_add_component(bpy.types.Operator):
    bl_idname = "hive.add_component"
    bl_label = "Add Component"
    bl_description = "Add premade guides; Rebuild turns them into bones and controls"
    preset: bpy.props.EnumProperty(
        items=[("fingers", "Fingers", "Five fingers on each hand"), ("tail", "Tail", "A tail behind the pelvis")]
    )

    def execute(self, context):
        try:
            self.report({"INFO"}, change_components(find_rig(context), "add", self.preset))
        except RuntimeError as e:
            self.report({"ERROR"}, str(e))
            return {"CANCELLED"}
        return {"FINISHED"}


class HIVE_OT_remove_component(bpy.types.Operator):
    bl_idname = "hive.remove_component"
    bl_label = "Remove Component"
    bl_description = "Remove the selected guide's component and everything attached to it"

    def execute(self, context):
        obj = context.active_object
        if obj is None or not obj.get("hive_component"):
            self.report({"ERROR"}, "Select a guide of the component to remove")
            return {"CANCELLED"}
        try:
            self.report({"INFO"}, change_components(find_rig(context), "remove", obj["hive_component"]))
        except RuntimeError as e:
            self.report({"ERROR"}, str(e))
            return {"CANCELLED"}
        return {"FINISHED"}


class HIVE_OT_rebuild(bpy.types.Operator):
    bl_idname = "hive.rebuild"
    bl_label = "Rebuild Rig"
    bl_description = "Rebuild the skeleton and controls from the guides"
    keep_weights: bpy.props.BoolProperty(
        name="Keep Weights", default=True, description="Keep current skin weights where the bones still exist"
    )

    def execute(self, context):
        try:
            rebuild(find_rig(context), self.keep_weights)
        except RuntimeError as e:
            self.report({"ERROR"}, str(e))
            return {"CANCELLED"}
        return {"FINISHED"}


class HIVE_OT_match_limb(bpy.types.Operator):
    bl_idname = "hive.match_limb"
    bl_label = "Match IK/FK"
    bl_description = "Switch the limb between IK and FK without it moving"
    bl_options = {"REGISTER", "UNDO"}
    limb: bpy.props.StringProperty()
    to: bpy.props.EnumProperty(items=[("fk", "To FK", "Snap FK to the IK pose"), ("ik", "To IK", "Snap IK to the FK pose")])

    def execute(self, context):
        (ik_to_fk if self.to == "fk" else fk_to_ik)(find_rig(context), self.limb)
        return {"FINISHED"}


class HIVE_OT_mirror_pose(bpy.types.Operator):
    bl_idname = "hive.mirror_pose"
    bl_label = "Mirror Pose"
    bl_description = "Copy the selected controls' pose to the other side (or every control's, if none is selected)"
    bl_options = {"REGISTER", "UNDO"}
    source: bpy.props.EnumProperty(items=[("left", "Left to Right", ""), ("right", "Right to Left", "")])

    def execute(self, context):
        rig = find_rig(context)
        n = mirror_pose(rig, selected_controls(rig), self.source)
        self.report({"INFO"}, "Mirrored %d controls" % n)
        return {"FINISHED"}


class HIVE_OT_reset_pose(bpy.types.Operator):
    bl_idname = "hive.reset_pose"
    bl_label = "Reset Pose"
    bl_description = "Put controls back to the bind pose and default settings"
    bl_options = {"REGISTER", "UNDO"}
    selected: bpy.props.BoolProperty(name="Selected Only", default=False)

    def execute(self, context):
        rig = find_rig(context)
        names = selected_controls(rig) if self.selected else None
        if self.selected and not names:
            self.report({"WARNING"}, "Select the controls to reset")
            return {"CANCELLED"}
        reset_pose(rig, names)
        return {"FINISHED"}


class HIVE_OT_select_controls(bpy.types.Operator):
    bl_idname = "hive.select_controls"
    bl_label = "Select All Controls"
    bl_description = "Select every animation control of the rig"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        rig = find_rig(context)
        if context.mode != "POSE":
            context.view_layer.objects.active = rig
            bpy.ops.object.mode_set(mode="POSE")
        select_controls(rig)
        return {"FINISHED"}


class HIVE_OT_switch_space(bpy.types.Operator):
    bl_idname = "hive.switch_space"
    bl_label = "Switch Space"
    bl_description = "Make the control follow another space without moving it"
    bl_options = {"REGISTER", "UNDO"}
    control: bpy.props.StringProperty()
    index: bpy.props.IntProperty()

    def execute(self, context):
        switch_space(find_rig(context), self.control, self.index)
        return {"FINISHED"}


class HIVE_PT_panel(bpy.types.Panel):
    bl_label = "Hive Rig"
    bl_space_type = "VIEW_3D"
    bl_region_type = "UI"
    bl_category = "Hive"

    def draw(self, context):
        layout = self.layout
        rig = find_rig(context)
        if rig is None:
            layout.label(text="No Hive rig in this file")
            return
        layout.label(text=rig["hive_name"])
        editing = bool(guide_objects(rig))
        col = layout.column(align=True)
        col.operator("hive.edit_guides", icon="EMPTY_DATA")
        sub = col.column(align=True)
        sub.enabled = editing
        sub.operator("hive.mirror_guides", icon="MOD_MIRROR")
        col = layout.column(align=True)
        col.label(text="Components")
        col.operator("hive.add_component", text="Add Fingers").preset = "fingers"
        col.operator("hive.add_component", text="Add Tail").preset = "tail"
        col.operator("hive.remove_component", icon="X")
        layout.operator("hive.rebuild", icon="FILE_REFRESH").keep_weights = True
        if editing or not rig.get("hive_anim"):
            return

        data = anim_data(rig)
        box = layout.box()
        box.label(text="Animation")
        pose = rig.pose.bones
        for limb in data["limbs"]:
            row = box.row(align=True)
            ik_on = pose[limb["ik"]].get("ik_fk", 0.0) >= 0.5
            row.label(text="%s (%s)" % (limb["name"], "IK" if ik_on else "FK"))
            op = row.operator("hive.match_limb", text="IK to FK")
            op.limb, op.to = limb["name"], "fk"
            op = row.operator("hive.match_limb", text="FK to IK")
            op.limb, op.to = limb["name"], "ik"
        row = box.row(align=True)
        row.operator("hive.mirror_pose", text="Mirror L to R", icon="MOD_MIRROR").source = "left"
        row.operator("hive.mirror_pose", text="Mirror R to L").source = "right"
        row = box.row(align=True)
        row.operator("hive.reset_pose", text="Reset All", icon="LOOP_BACK").selected = False
        row.operator("hive.reset_pose", text="Reset Selected").selected = True
        box.operator("hive.select_controls", icon="RESTRICT_SELECT_OFF")
        active = context.active_pose_bone
        if active is not None and active.id_data == rig and active.name in data["spaces"]:
            col = box.column(align=True)
            col.label(text="Space of %s (no pop)" % active.name)
            for i, space in enumerate(data["spaces"][active.name]):
                op = col.operator("hive.switch_space", text=space, depress=int(active.get("space", 0)) == i)
                op.control, op.index = active.name, i


CLASSES = (
    HIVE_OT_edit_guides,
    HIVE_OT_mirror_guides,
    HIVE_OT_add_component,
    HIVE_OT_remove_component,
    HIVE_OT_rebuild,
    HIVE_OT_match_limb,
    HIVE_OT_mirror_pose,
    HIVE_OT_reset_pose,
    HIVE_OT_select_controls,
    HIVE_OT_switch_space,
    HIVE_PT_panel,
)


def register():
    for cls in CLASSES:
        if hasattr(bpy.types, cls.__name__):
            bpy.utils.unregister_class(getattr(bpy.types, cls.__name__))
        bpy.utils.register_class(cls)


def main():
    existing = bpy.data.objects.get(RIG_DATA["name"] + "_rig")
    if existing is not None and existing.get("hive_guides"):
        print("hive-rig: %s is already in this file; the Hive tab is ready" % RIG_DATA["name"])
    else:
        build(RIG_DATA)
    register()

    # Optional: `-- --save path.blend` when run headless.
    if "--" in sys.argv:
        args = sys.argv[sys.argv.index("--") + 1 :]
        if "--save" in args:
            bpy.ops.wm.save_as_mainfile(filepath=args[args.index("--save") + 1])


if __name__ == "__main__":
    main()
